import{_ as t,o as e,c as r,ai as l}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"Go 语言总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/go/language.md","filePath":"tech-system/backend/go/language.md"}'),o={name:"tech-system/backend/go/language.md"};function i(n,a,d,h,s,c){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="go-语言总结" tabindex="-1">Go 语言总结 <a class="header-anchor" href="#go-语言总结" aria-label="Permalink to “Go 语言总结”">​</a></h1><blockquote><p>我对 Go 的定位：<strong>能读能改、能写小服务</strong>，不是第二主栈。</p></blockquote><hr><h2 id="go-的核心特点" tabindex="-1">Go 的核心特点 <a class="header-anchor" href="#go-的核心特点" aria-label="Permalink to “Go 的核心特点”">​</a></h2><ul><li>语法少，上手曲线平</li><li><strong>Goroutine + Channel</strong>：并发模型直观</li><li>编译成单二进制，部署友好</li><li>标准库强，很多事不必先找框架</li></ul><hr><h2 id="并发与性能边界" tabindex="-1">并发与性能边界 <a class="header-anchor" href="#并发与性能边界" aria-label="Permalink to “并发与性能边界”">​</a></h2><ul><li>适合网络 IO、worker、代理类服务</li><li>不是自动让业务变简单；域复杂时表达力不如 Java 生态省心</li><li>错误处理显式：烦，但线上问题少「吞异常」</li></ul><hr><h2 id="适合什么-不适合什么" tabindex="-1">适合什么 / 不适合什么 <a class="header-anchor" href="#适合什么-不适合什么" aria-label="Permalink to “适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合（对我而言）</th></tr></thead><tbody><tr><td>边车、网关、高并发小工具</td><td>取代 Java 做整套 CRM/ERP</td></tr><tr><td>云原生组件、简单 API</td><td>快速 AI 试错（Python 更快）</td></tr><tr><td>对内存/部署体积敏感</td><td>团队不会 Go 却强行全量迁移</td></tr></tbody></table><hr><h2 id="我为什么了解-go" tabindex="-1">我为什么了解 Go <a class="header-anchor" href="#我为什么了解-go" aria-label="Permalink to “我为什么了解 Go”">​</a></h2><ul><li>读开源、改小服务时用得上</li><li>并发与部署思路能反哺 Java 架构讨论</li><li>不与 Java 抢主业务，做 <strong>补位技能</strong></li></ul><p>框架 → <a href="./frameworks.html">Go 框架总结</a></p>',15)])])}const b=t(o,[["render",i]]);export{_ as __pageData,b as default};
